class Solution:
    def maxValidPairSum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ans = 0
        for j in range(k, n):
            for i in range(j - k + 1):
                ans = max(ans, nums[i] + nums[j])
        return ans

