class Solution {
public:
    long long maxValidPairSum(vector<int>& nums, int k) {
        int n = nums.size();
        long long ans = 0;
        for (int j = k; j < n; j++)
            for (int i = 0; i + k <= j; i++)
                ans = max(ans, (long long)nums[i] + nums[j]);
        return ans;
    }
};

